$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Zero and identity operators
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Define the Hilbert space zero operator.  See ~ df0op2 for alternate
     definition.  (Contributed by NM, 7-Feb-2006.)
     (New usage is discouraged.) $)
  df-h0op $a |- 0hop = ( projh ` 0H ) $.

  $( Define the Hilbert space identity operator.  See ~ dfiop2 for alternate
     definition.  (Contributed by NM, 15-Nov-2000.)
     (New usage is discouraged.) $)
  df-iop $a |- Iop = ( projh ` ~H ) $.

  $( Value of the zero Hilbert space operator (null projector).  Remark in
     [Beran] p. 111.  (Contributed by NM, 7-Feb-2006.)
     (New usage is discouraged.) $)
  ho0val $p |- ( A e. ~H -> ( 0hop ` A ) = 0h ) $=
    ( chba wcel ch0o cfv cpjh cmv co c0v c0h choc1 fveq2i df-h0op eqtr4i fveq1i
    cort cch wceq helch pjo mpan eqtr3id pjhcli hvsubid syl eqtrd ) ABCZADEZABF
    EEZUIGHZIUGUHABPEZFEZEZUJAULDULJFEDUKJFKLMNOBQCUGUMUJRSABTUAUBUGUIBCUJIRABS
    UCUIUDUEUF $.

  $( Functionality of the zero Hilbert space operator.  (Contributed by NM,
     10-Mar-2006.)  (New usage is discouraged.) $)
  ho0f $p |- 0hop : ~H --> ~H $=
    ( chba ch0o wf c0h cpjh cfv h0elch pjfi df-h0op feq1i mpbir ) AABCAADEFZCDG
    HAABLIJK $.

  $( Alternate definition of Hilbert space zero operator.  (Contributed by NM,
     7-Aug-2006.)  (New usage is discouraged.) $)
  df0op2 $p |- 0hop = ( ~H X. 0H ) $=
    ( vx ch0o chba c0v csn cxp c0h wf wceq wfn cv cfv wral ho0f ffn ho0val rgen
    ax-mp fconstfv mpbir2an ax-hv0cl elexi fconst2 mpbi df-ch0 xpeq2i eqtr4i )
    BCDEZFZCGFCUHBHZBUIIUJBCJZAKZBLDIZACMCCBHUKNCCBORUMACULPQACDBSTCDBDCUAUBUCU
    DGUHCUEUFUG $.

  $( Alternate definition of Hilbert space identity operator.  (Contributed by
     NM, 7-Aug-2006.)  (New usage is discouraged.) $)
  dfiop2 $p |- Iop = ( _I |` ~H ) $=
    ( vx chio chba cpjh cfv cid cres df-iop wfn wceq helch pjfni fnresi wa wral
    cv wcel pjch1 fvresi eqtr4d rgen eqfnfv mpbiri mp2an eqtri ) BCDEZFCGZHUFCI
    ZUGCIZUFUGJZCKLCMUHUINUJAPZUFEZUKUGEZJZACOUNACUKCQULUKUMUKRCUKSTUAACUFUGUBU
    CUDUE $.

  $( Functionality of the Hilbert space identity operator.  (Contributed by NM,
     8-Aug-2006.)  (New usage is discouraged.) $)
  hoif $p |- Iop : ~H -1-1-onto-> ~H $=
    ( chba chio wf1o cid cres f1oi wceq wb dfiop2 f1oeq1 ax-mp mpbir ) AABCZAAD
    AEZCZAFBNGMOHIAABNJKL $.

  $( The value of the Hilbert space identity operator.  (Contributed by NM,
     8-Aug-2006.)  (New usage is discouraged.) $)
  hoival $p |- ( A e. ~H -> ( Iop ` A ) = A ) $=
    ( chba wcel chio cfv cpjh df-iop fveq1i pjch1 eqtrid ) ABCADEABFEZEAADKGHAI
    J $.

  $( Composition with the Hilbert space identity operator.  (Contributed by NM,
     24-Aug-2006.)  (New usage is discouraged.) $)
  hoico1 $p |- ( T : ~H --> ~H -> ( T o. Iop ) = T ) $=
    ( chba wf chio ccom cid cres dfiop2 coeq2i fcoi1 eqtrid ) BBACADEAFBGZEADLA
    HIBBAJK $.

  $( Composition with the Hilbert space identity operator.  (Contributed by NM,
     24-Aug-2006.)  (New usage is discouraged.) $)
  hoico2 $p |- ( T : ~H --> ~H -> ( Iop o. T ) = T ) $=
